#include <cmath>
#include "pbrt.h"
#include "geometry.h"

namespace pbrt {

Vector3f CosineSampleHemisphere(const Point2f &u) {
    // Map _u_ to $[-1,1]^2$ and handle degeneracy at the origin
    Point2f uOffset = 2.f * u - Vector2f(1, 1);
    if (uOffset.x == 0 && uOffset.y == 0) return Vector3f(0, 0, 1);

    // Apply concentric mapping to point
    Float theta, r;
    if (std::abs(uOffset.x) > std::abs(uOffset.y)) {
        r = uOffset.x;
        theta = (Pi / 4) * (uOffset.y / uOffset.x);
    } else {
        r = uOffset.y;
        theta = (Pi / 2) - (Pi / 4) * (uOffset.x / uOffset.y);
    }
    Float dx = r * std::cos(theta);
    Float dy = r * std::sin(theta);

    // Compute $z$ component for cosine-weighted hemisphere
    Float z = std::sqrt(1 - dx * dx - dy * dy);
    return Vector3f(dx, dy, z);
}

} // namespace pbrt

